"use strict";
// Cyrus STARTER BANK (MB_STARTER_BANK=1, default off): prebuilt, Nxeon-authored, golden-verified mods for the house starter
// templates and the commonest simple archetypes. A bank build makes ZERO model calls: the entry's verified source tree is copied
// into the workspace, the request's parameters become the defaults of its settings schema (assets/config/schema.json, so the
// Config Studio can change them later), and then the SAME non-AI checks as every build run (validate, pre-check, perf check,
// settings check, javac with the perf watchdog, warning rules, bytecode + source scan). The portal still runs Test Flight.
//
// Content rules (D-60 / D-61): every entry is written by Nxeon from our own golden plugins; nothing comes from a user's build,
// an imported mod or the reference corpus. This is NOT MB_DEDUPE (which would serve one user's build to another and stays off).
//
// Layout: bank/<id>/entry.json (id, version, title, archetype, pluginName, mcVersions), plugin.yml, schema.json (ConfigSpec v1),
// modbuilder.json (summary shown to the customer), src/** (Java, package dev.nxeon.starter.<id>). Plain Node, no dependencies.
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const BANK_DIR = path.join(__dirname, "bank");
const ID_RE = /^[a-z][a-z0-9-]{1,31}$/;
const enabled = (env = process.env) => env.MB_STARTER_BANK === "1";

function walk(root, rel = "") {
  const out = [];
  let es = [];
  try { es = fs.readdirSync(path.join(root, rel), { withFileTypes: true }); } catch { return out; }
  for (const e of es.sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) out.push(...walk(root, r));
    else out.push({ rel: r, abs: path.join(root, r) });
  }
  return out;
}

let cache = null;
/** id -> entry (entry.json + dir + sha256 over every file). Bad entries are skipped and listed in `problems`. */
function loadEntries(dir = BANK_DIR) {
  if (cache && cache.dir === dir) return cache;
  const entries = new Map();
  const problems = [];
  let ids = [];
  try { ids = fs.readdirSync(dir, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort(); } catch { ids = []; }
  for (const id of ids) {
    const d = path.join(dir, id);
    try {
      const e = JSON.parse(fs.readFileSync(path.join(d, "entry.json"), "utf8"));
      if (e.id !== id || !ID_RE.test(id)) throw new Error("entry.json id must equal the folder name");
      for (const f of ["plugin.yml", "schema.json", "modbuilder.json"]) if (!fs.existsSync(path.join(d, f))) throw new Error(`${f} missing`);
      const files = walk(d).filter((f) => f.rel !== "entry.json");
      if (!files.some((f) => f.rel.startsWith("src/") && f.rel.endsWith(".java"))) throw new Error("no Java sources under src/");
      const h = crypto.createHash("sha256");
      for (const f of files) h.update(f.rel + "\0").update(fs.readFileSync(f.abs));
      const schema = JSON.parse(fs.readFileSync(path.join(d, "schema.json"), "utf8"));
      entries.set(id, { ...e, dir: d, sha256: h.digest("hex"), paramKeys: (schema.params || []).map((p) => p.key) });
    } catch (err) { problems.push(`${id}: ${String(err.message || err).slice(0, 160)}`); }
  }
  cache = { dir, entries, problems };
  return cache;
}
const entries = (dir) => loadEntries(dir).entries;

/** One fingerprint of the whole bank (release record + knowledge facts). */
function bankVersion(dir) {
  const h = crypto.createHash("sha256");
  for (const e of entries(dir).values()) h.update(`${e.id}@${e.version}:${e.sha256}\n`);
  return `bank-${h.digest("hex").slice(0, 12)}`;
}

const SAFE_TEXT = /^[^\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]*$/;
/**
 * The `bank` field of POST /builds: { id, params? }. Returns null (absent), { error } or { id, version, sha256, params }.
 * Params are checked against the entry's schema: known keys only, the param's type, numbers inside the crash-safe bounds
 * (hardMin / hardMax; the recommended range only warns, D-62), text without control characters within maxLength.
 */
function parseBankRequest(b, mcVersion, dir) {
  if (b === undefined || b === null) return null;
  if (typeof b !== "object" || Array.isArray(b)) return { error: "bank must be an object { id, params }" };
  const id = String(b.id || "");
  const e = entries(dir).get(id);
  if (!e) return { error: `no starter bank entry ${id.slice(0, 40)}` };
  if (Array.isArray(e.mcVersions) && !e.mcVersions.includes(mcVersion)) return { error: `starter bank entry ${id} is not verified for ${mcVersion}` };
  const spec = JSON.parse(fs.readFileSync(path.join(e.dir, "schema.json"), "utf8"));
  const byKey = new Map((spec.params || []).map((p) => [p.key, p]));
  const raw = b.params && typeof b.params === "object" && !Array.isArray(b.params) ? b.params : {};
  const params = {};
  for (const [k, v] of Object.entries(raw).slice(0, 40)) {
    const p = byKey.get(k);
    if (!p) return { error: `starter bank entry ${id} has no setting ${String(k).slice(0, 60)}` };
    if (["number", "int", "duration"].includes(p.type)) {
      if (typeof v !== "number" || !Number.isFinite(v)) return { error: `${k} must be a number` };
      if (p.type === "int" && !Number.isInteger(v)) return { error: `${k} must be a whole number` };
      if ((p.hardMin !== undefined && v < p.hardMin) || (p.hardMax !== undefined && v > p.hardMax)) return { error: `${k} is outside its safe bounds` };
    } else if (p.type === "bool") {
      if (typeof v !== "boolean") return { error: `${k} must be true or false` };
    } else if (p.type === "text" || p.type === "enum") {
      if (typeof v !== "string" || !SAFE_TEXT.test(v) || v.length > (p.maxLength || 200)) return { error: `${k} must be a short text` };
      if (p.type === "enum" && !(p.options || []).some((o) => o.value === v)) return { error: `${k} must be one of its options` };
    } else return { error: `${k} cannot be set from the request` };
    params[k] = v;
  }
  return { id, version: e.version, sha256: e.sha256, params };
}

/** The entry's schema with the request's params as the defaults (a copy; the file is never edited). */
function specWithParams(e, params) {
  const spec = JSON.parse(fs.readFileSync(path.join(e.dir, "schema.json"), "utf8"));
  for (const p of spec.params || []) if (params && Object.prototype.hasOwnProperty.call(params, p.key)) p.default = params[p.key];
  return spec;
}

/** Copy one entry into a workspace that already holds the Gradle template. Returns the relative paths written. */
function materialize(id, params, ws, dir) {
  const e = entries(dir).get(id);
  if (!e) throw new Error(`no starter bank entry ${id}`);
  const written = [];
  const put = (rel, buf) => { const abs = path.join(ws, rel); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, buf); written.push(rel); };
  for (const f of walk(e.dir)) {
    if (f.rel.startsWith("src/")) put(`src/main/java/${f.rel.slice(4)}`, fs.readFileSync(f.abs));
    else if (f.rel === "plugin.yml") put("src/main/resources/plugin.yml", fs.readFileSync(f.abs));
    else if (f.rel === "modbuilder.json") put("modbuilder.json", fs.readFileSync(f.abs));
  }
  put("assets/config/schema.json", JSON.stringify(specWithParams(e, params), null, 1) + "\n");
  return written;
}

/** Public list for GET /health and the portal consistency test (no file contents). */
function catalogue(dir) {
  return [...entries(dir).values()].map((e) => ({ id: e.id, version: e.version, title: e.title, archetype: e.archetype, mcVersions: e.mcVersions, params: e.paramKeys, sha256: e.sha256 }));
}

function resetCache() { cache = null; }

module.exports = { BANK_DIR, enabled, loadEntries, entries, bankVersion, parseBankRequest, specWithParams, materialize, catalogue, resetCache, walk };
"use strict";
// Cyrus RECIPE MEMORY v1 (MB_RECIPES=1, default off; design: agent-notes BL-recipe-memory-design.md). A recipe is a small,
// verified, generic implementation pattern for one mechanic (cooldown map, per-player persistent data, safe teleport, bounded
// block work with NxPerf, item model states, particle bursts, combat tag, per-player fx, mob capture, chest-menu anti-dupe),
// written by Nxeon from our own golden plugins and technique notes. Each file carries ids, a version, the Paper versions it
// was proven on and its proof (the golden plugin whose compile + scan + Test Flight rows in golden/results.json pass).
//
// Selection is deterministic and free (no model call): word rules per recipe, cross-checked by the archetype ids the intake
// guard may return in the same Haiku call (route.js GUARD_PROMPT_RECIPES). Only VERIFIED recipes are injected, at most two,
// into the FIRST USER TURN (never the system prompt, so the cached prefix stays byte-identical). A deterministic HOLDBACK
// (MB_RECIPES_HOLDBACK_PCT, default 20% of matching builds by build id) gets no injection, so the effect can be measured.
// Off = nothing is selected, recorded or injected; the prompts are byte-identical to before (tested).
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const RECIPE_DIR = path.join(__dirname, "recipes");
const MAX_RECIPES = 2;
const MAX_BLOCK_CHARS = 3600; // about 900 tokens per recipe (BL design budget)
const enabled = (env = process.env) => env.MB_RECIPES === "1";
const holdbackPct = (env = process.env) => { const n = parseInt(env.MB_RECIPES_HOLDBACK_PCT || "", 10); return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 20; };

let cache = null;
function loadRecipes(dir = RECIPE_DIR) {
  if (cache && cache.dir === dir) return cache.list;
  const list = [];
  let files = [];
  try { files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort(); } catch { files = []; }
  for (const f of files) {
    try {
      const r = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
      if (r.id !== f.replace(/\.json$/, "")) continue;
      list.push({ ...r, _match: (r.match || []).map((s) => new RegExp(s, "i")), _strong: (r.strong || []).map((s) => new RegExp(s, "i")), _not: (r.not || []).map((s) => new RegExp(s, "i")) });
    } catch { /* a damaged file is skipped (the lint test fails on it) */ }
  }
  cache = { dir, list };
  return list;
}

function recipesVersion(dir) {
  const h = crypto.createHash("sha256");
  for (const r of loadRecipes(dir)) h.update(`${r.id}@${r.version}:${r.status}\n`);
  return `rcp-${h.digest("hex").slice(0, 12)}`;
}

/** The closed list of archetype ids the guard may return (the archetypes our verified recipes cover). */
function guardArchetypes(dir) {
  return [...new Set(loadRecipes(dir).filter((r) => r.status === "verified").flatMap((r) => r.archetypes || []))].sort();
}

/** Word score of one recipe for a request: each match rule = 1, each strong rule = 2; any `not` rule = 0. */
function scoreOf(r, text) {
  if (r._not.some((re) => re.test(text))) return 0;
  return r._match.filter((re) => re.test(text)).length + 2 * r._strong.filter((re) => re.test(text)).length;
}

const lanesOf = (assets) => {
  const a = assets || {};
  return { texture: !!a.texture, design: !!a.design, sound: !!a.sound, datapack: !!a.datapack, creature: !!a.creature, itemmodel: !!a.itemmodel };
};

/**
 * Pick the recipes for a FRESH build. Returns { ids, picks: [{id, version, score, source}], considered }. Never for change
 * builds, imports or designer builds (Nxeon generates their code from the design). A recipe needs a score of 2 (two word rules
 * or one strong rule), or 1 when the guard named one of its archetypes. A wrong recipe is worse than none: ties and weak
 * single-word hits inject nothing.
 */
function selectRecipes(text, opts = {}, dir) {
  const t = String(text || "");
  if (!t.trim() || opts.change || opts.imported) return { ids: [], picks: [], considered: 0 };
  const lanes = lanesOf(opts.assets);
  if (lanes.design) return { ids: [], picks: [], considered: 0 };
  const guard = new Set(opts.guardArchetypes || []);
  const scored = [];
  for (const r of loadRecipes(dir)) {
    if (r.status !== "verified") continue;
    if (opts.mcVersion && Array.isArray(r.mcVersions) && !r.mcVersions.includes(opts.mcVersion)) continue;
    if ((r.requiresAssets || []).some((k) => !lanes[k])) continue;
    const s = scoreOf(r, t);
    const byGuard = (r.archetypes || []).some((a) => guard.has(a));
    if (s >= 2 || (s >= 1 && byGuard)) scored.push({ r, score: s + (byGuard ? 1 : 0), source: byGuard ? (s >= 2 ? "rules+guard" : "guard+rules") : "rules" });
  }
  scored.sort((a, b) => b.score - a.score || a.r.id.localeCompare(b.r.id));
  const picks = [];
  for (const x of scored) {
    if (picks.length >= MAX_RECIPES) break;
    // a second recipe only when it shares no pitfall with the first (BL design: one recipe, two only if disjoint)
    if (picks.length && (x.r.pitfalls || []).some((p) => (picks[0].r.pitfalls || []).some((q) => q.ruleId && q.ruleId === p.ruleId))) continue;
    picks.push(x);
  }
  return { ids: picks.map((x) => x.r.id), picks: picks.map((x) => ({ id: x.r.id, version: x.r.version, score: x.score, source: x.source })), considered: scored.length };
}

/** Deterministic A/B: this build is in the holdback (no injection) when hash(build id) mod 100 < pct. */
function isHoldback(buildId, pct = holdbackPct()) {
  if (pct <= 0) return false;
  if (pct >= 100) return true;
  const n = parseInt(crypto.createHash("sha1").update(`cyrus-recipes:${buildId}`).digest("hex").slice(0, 8), 16) % 100;
  return n < pct;
}

/** The user-turn block for the picked recipes (empty string for none). */
function recipeBlock(ids, dir) {
  const all = new Map(loadRecipes(dir).map((r) => [r.id, r]));
  const parts = [];
  for (const id of ids || []) {
    const r = all.get(id);
    if (!r) continue;
    const settings = (r.configSchema || []).map((c) => `${c.key} (${c.type}, default ${JSON.stringify(c.default)}${c.why ? `: ${c.why}` : ""})`).join("; ");
    const pit = (r.pitfalls || []).map((p) => `- ${p.note}`).join("\n");
    const text = `TESTED PATTERN for this kind of mod (follow it unless the request needs something else): ${r.title}\n${r.pattern}${settings ? `\nSettings to expose: ${settings}` : ""}${pit ? `\nKnown pitfalls:\n${pit}` : ""}`;
    parts.push(text.slice(0, MAX_BLOCK_CHARS));
  }
  return parts.length ? `\n${parts.join("\n\n")}\n` : "";
}

/**
 * One call for server.js: what to record on the build and the block to inject (null when off, nothing matched, or holdback).
 * record = { version, ids, picks, holdback, injected, holdbackPct }.
 */
function forBuild(rec, opts = {}, env = process.env, dir) {
  if (!enabled(env)) return null;
  const sel = selectRecipes(rec.prompt, { mcVersion: rec.mcVersion, assets: rec.assets, change: !!rec.baseBuildId, imported: !!rec.imported, guardArchetypes: opts.guardArchetypes || rec.guardArchetypes || [] }, dir);
  if (!sel.ids.length) return { record: { version: recipesVersion(dir), ids: [], picks: [], holdback: false, injected: false, holdbackPct: holdbackPct(env) }, block: "" };
  const hold = isHoldback(rec.id, holdbackPct(env));
  return { record: { version: recipesVersion(dir), ids: sel.ids, picks: sel.picks, holdback: hold, injected: !hold, holdbackPct: holdbackPct(env) }, block: hold ? "" : recipeBlock(sel.ids, dir) };
}

function resetCache() { cache = null; }

module.exports = { RECIPE_DIR, MAX_RECIPES, MAX_BLOCK_CHARS, enabled, holdbackPct, loadRecipes, recipesVersion, guardArchetypes, scoreOf, selectRecipes, isHoldback, recipeBlock, forBuild, resetCache };
"use strict";
// Cyrus capacity (2026-10-14): the knobs and safety parts around the scheduler (scheduler.js). PURE except
// readContainerLimits (reads cgroup files, never writes). Unit-tested in test/modbuilder-capacity.test.ts.
//
//   - deriveConcurrency: a safe MB_CONCURRENCY from the container's memory and CPU limits (MB_CONCURRENCY=auto uses it;
//     /health capacity.suggestedConcurrency always reports it). Per-build footprint MB_PER_BUILD_MB (default 1200,
//     PLACEHOLDER until measured on the build VM: see docs/cyrus/07-operations.md "Build capacity").
//   - samples: recent run and wait durations -> p50/p80 (the honest estimates; no samples = no estimate).
//   - breaker: the AI circuit breaker. A session/rate limit answer from the AI backend opens it (exponential backoff,
//     MB_AI_BACKOFF_S doubling up to MB_AI_BACKOFF_MAX_S); while open, no NEW AI build starts (non-AI work still runs) and the
//     builds that hit the limit wait in line for an automatic retry (MB_AI_RETRIES) instead of failing. After the backoff
//     ONE build probes (half-open); its success closes the breaker.
//   - isAiLimit: is this AI error text a limit/overload (retry later) rather than a real failure.
const fs = require("fs");
const os = require("os");

function int(v, d) { const n = parseInt(v == null ? "" : String(v), 10); return Number.isFinite(n) ? n : d; }

const AI_LIMIT = /session limit|usage limit|rate.?limit|too many requests|\b429\b|\b529\b|overloaded|limit reached|resets? (?:at )?\d/i;
function isAiLimit(text) { return AI_LIMIT.test(String(text || "")); }

/** Memory (bytes) and CPU count the container may use: cgroup v2, then v1, then the host. */
function readContainerLimits(read = (f) => fs.readFileSync(f, "utf8")) {
  let memBytes = null, cpus = null;
  const tryRead = (f) => { try { return String(read(f)).trim(); } catch { return null; } };
  const m2 = tryRead("/sys/fs/cgroup/memory.max");
  if (m2 && /^\d+$/.test(m2)) memBytes = Number(m2);
  if (memBytes === null) { const m1 = tryRead("/sys/fs/cgroup/memory/memory.limit_in_bytes"); if (m1 && /^\d+$/.test(m1) && Number(m1) < 2 ** 60) memBytes = Number(m1); }
  const c2 = tryRead("/sys/fs/cgroup/cpu.max");
  if (c2) { const [q, p] = c2.split(/\s+/); if (/^\d+$/.test(q) && /^\d+$/.test(p) && Number(p) > 0) cpus = Number(q) / Number(p); }
  if (cpus === null) { const q = tryRead("/sys/fs/cgroup/cpu/cpu.cfs_quota_us"), p = tryRead("/sys/fs/cgroup/cpu/cpu.cfs_period_us"); if (q && p && Number(q) > 0 && Number(p) > 0) cpus = Number(q) / Number(p); }
  const host = { memBytes: os.totalmem(), cpus: (os.cpus() || []).length || 1 };
  return { memBytes: memBytes ?? host.memBytes, cpus: cpus ?? host.cpus, source: memBytes !== null ? "cgroup" : "host" };
}

/**
 * How many builds can run at once without the container hitting its memory limit:
 * floor((memory - base) / perBuild), at most 2 builds per CPU (a build mostly waits on the model; javac is the CPU burst),
 * at least 1. Defaults: base 600 MB (service + JVM tools idle), per build 1200 MB (CLI ~0.4-0.5 GB + javac peak ~0.6 GB +
 * slack), both PLACEHOLDER until measured on the build VM.
 */
function deriveConcurrency({ memBytes, cpus, perBuildMb = 1200, baseMb = 600 }) {
  const memMb = Math.floor((memBytes || 0) / 1048576);
  const byMem = Math.floor((memMb - baseMb) / Math.max(1, perBuildMb));
  const byCpu = Math.max(1, Math.floor((cpus || 1) * 2));
  return { suggested: Math.max(1, Math.min(byMem, byCpu)), byMem: Math.max(0, byMem), byCpu, memMb, perBuildMb, baseMb };
}

function capacityConfig(env, limits) {
  const lim = limits || { memBytes: os.totalmem(), cpus: 1 };
  const derived = deriveConcurrency({ memBytes: lim.memBytes, cpus: lim.cpus, perBuildMb: int(env.MB_PER_BUILD_MB, 1200), baseMb: int(env.MB_BASE_MB, 600) });
  const raw = String(env.MB_CONCURRENCY || "").trim().toLowerCase();
  const concurrency = raw === "auto" ? derived.suggested : Math.max(1, int(raw, 2));
  return {
    concurrency, concurrencySource: raw === "auto" ? "auto" : raw ? "env" : "default", derived,
    accountMaxActive: Math.max(0, int(env.MB_ACCOUNT_MAX_ACTIVE, 3)),
    queueMax: Math.max(1, int(env.MB_QUEUE_MAX, 40)),
    queueMaxBatch: Math.max(0, int(env.MB_QUEUE_MAX_BATCH, 30)),
    aiRetries: Math.max(0, int(env.MB_AI_RETRIES, 2)),
    backoffMs: Math.max(5, int(env.MB_AI_BACKOFF_S, 60)) * 1000,
    backoffMaxMs: Math.max(5, int(env.MB_AI_BACKOFF_MAX_S, 900)) * 1000,
  };
}

/** A bounded list of recent durations (ms) with percentiles. */
function createSamples(max = 60) {
  const xs = [];
  const q = (p) => {
    if (!xs.length) return null;
    const s = xs.slice().sort((a, b) => a - b);
    return s[Math.min(s.length - 1, Math.max(0, Math.ceil(p * s.length) - 1))];
  };
  return {
    add(ms) { if (Number.isFinite(ms) && ms >= 0) { xs.push(ms); if (xs.length > max) xs.shift(); } },
    count: () => xs.length,
    p: q,
    summary(minSamples = 5) {
      const n = xs.length;
      return n >= minSamples ? { p50: q(0.5), p80: q(0.8), n } : { p50: null, p80: null, n };
    },
  };
}

function createBreaker({ baseMs = 60_000, maxMs = 900_000 } = {}) {
  let failures = 0, openUntil = 0, probing = false, trips = 0, lastReason = null;
  return {
    /** An AI limit answer: open (or re-open, doubled) the breaker. Returns the time it may probe again. */
    trip(t, reason) {
      trips++; lastReason = String(reason || "").slice(0, 160);
      // builds that hit the same limit while it is already open count once (no doubling for a burst)
      if (failures && t < openUntil && !probing) return openUntil;
      failures++; probing = false;
      openUntil = t + Math.min(maxMs, baseMs * 2 ** (failures - 1));
      return openUntil;
    },
    success() { failures = 0; openUntil = 0; probing = false; },
    /** May a NEW AI build start now? Half-open lets exactly one through until it reports back. */
    allow(t) {
      if (!failures) return true;
      if (t < openUntil || probing) return false;
      probing = true;
      return true;
    },
    /** The probe ended without an AI answer either way (cancelled, non-AI failure): let another one try. */
    release() { probing = false; },
    openUntil: () => (failures ? openUntil : 0),
    state(t) { return !failures ? "closed" : t < openUntil ? "open" : probing ? "probing" : "half-open"; },
    view(t) { return { state: this.state(t), until: failures ? new Date(openUntil).toISOString() : null, failures, trips, reason: lastReason }; },
  };
}

module.exports = { isAiLimit, readContainerLimits, deriveConcurrency, capacityConfig, createSamples, createBreaker };
